#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Render one structured analysis payload into Markdown and HTML dashboards.

Chart URLs are generated by the chart-visualization skill. This renderer does
not draw charts and deliberately validates the chart tool/args contract before
writing the Markdown report or either HTML file.
"""

from __future__ import annotations

import argparse
import html
import json
from pathlib import Path
from typing import Any


DARK_BACKGROUND = "#101418"
LIGHT_BACKGROUND = "#ffffff"

THEMED_TOOLS = {
    "generate_area_chart",
    "generate_bar_chart",
    "generate_boxplot_chart",
    "generate_column_chart",
    "generate_dual_axes_chart",
    "generate_fishbone_diagram",
    "generate_flow_diagram",
    "generate_funnel_chart",
    "generate_histogram_chart",
    "generate_line_chart",
    "generate_liquid_chart",
    "generate_mind_map",
    "generate_network_graph",
    "generate_organization_chart",
    "generate_pie_chart",
    "generate_radar_chart",
    "generate_sankey_chart",
    "generate_scatter_chart",
    "generate_spreadsheet",
    "generate_treemap_chart",
    "generate_venn_chart",
    "generate_violin_chart",
    "generate_word_cloud_chart",
}

COMMON_CHART_FIELDS = {"theme", "width", "height", "title"}
STYLE_FIELDS_BY_TOOL = {
    "background": {"backgroundColor", "palette", "texture"},
    "line": {"backgroundColor", "palette", "texture", "lineWidth"},
    "texture": {"texture"},
    "liquid": {"backgroundColor", "color", "texture"},
    "none": set(),
}

CHART_FIELDS = {
    "generate_area_chart": COMMON_CHART_FIELDS | {"style", "data", "stack", "axisXTitle", "axisYTitle"},
    "generate_bar_chart": COMMON_CHART_FIELDS | {"style", "data", "group", "stack", "axisXTitle", "axisYTitle"},
    "generate_boxplot_chart": COMMON_CHART_FIELDS | {"style", "data", "axisXTitle", "axisYTitle"},
    "generate_column_chart": COMMON_CHART_FIELDS | {"style", "data", "group", "stack", "axisXTitle", "axisYTitle"},
    "generate_dual_axes_chart": COMMON_CHART_FIELDS | {"style", "categories", "series", "axisXTitle"},
    "generate_fishbone_diagram": COMMON_CHART_FIELDS | {"style", "data"},
    "generate_flow_diagram": COMMON_CHART_FIELDS | {"style", "data"},
    "generate_funnel_chart": COMMON_CHART_FIELDS | {"style", "data"},
    "generate_histogram_chart": COMMON_CHART_FIELDS | {"style", "data", "binNumber", "axisXTitle", "axisYTitle"},
    "generate_line_chart": COMMON_CHART_FIELDS | {"style", "data", "axisXTitle", "axisYTitle"},
    "generate_liquid_chart": COMMON_CHART_FIELDS | {"style", "percent", "shape"},
    "generate_mind_map": COMMON_CHART_FIELDS | {"style", "data"},
    "generate_network_graph": COMMON_CHART_FIELDS | {"style", "data"},
    "generate_organization_chart": COMMON_CHART_FIELDS | {"style", "data", "orient"},
    "generate_pie_chart": COMMON_CHART_FIELDS | {"style", "data", "innerRadius"},
    "generate_radar_chart": COMMON_CHART_FIELDS | {"style", "data"},
    "generate_sankey_chart": COMMON_CHART_FIELDS | {"style", "data", "nodeAlign"},
    "generate_scatter_chart": COMMON_CHART_FIELDS | {"style", "data", "axisXTitle", "axisYTitle"},
    "generate_spreadsheet": {"data", "rows", "columns", "values", "theme", "width", "height"},
    "generate_treemap_chart": COMMON_CHART_FIELDS | {"style", "data"},
    "generate_venn_chart": COMMON_CHART_FIELDS | {"style", "data"},
    "generate_violin_chart": COMMON_CHART_FIELDS | {"style", "data", "axisXTitle", "axisYTitle"},
    "generate_word_cloud_chart": COMMON_CHART_FIELDS | {"style", "data"},
}

STYLE_KIND_BY_TOOL = {
    "generate_area_chart": "line",
    "generate_bar_chart": "background",
    "generate_boxplot_chart": "background",
    "generate_column_chart": "background",
    "generate_dual_axes_chart": "background",
    "generate_fishbone_diagram": "texture",
    "generate_flow_diagram": "texture",
    "generate_funnel_chart": "background",
    "generate_histogram_chart": "background",
    "generate_line_chart": "line",
    "generate_liquid_chart": "liquid",
    "generate_mind_map": "texture",
    "generate_network_graph": "texture",
    "generate_organization_chart": "texture",
    "generate_pie_chart": "background",
    "generate_radar_chart": "line",
    "generate_sankey_chart": "background",
    "generate_scatter_chart": "background",
    "generate_spreadsheet": "none",
    "generate_treemap_chart": "background",
    "generate_venn_chart": "background",
    "generate_violin_chart": "background",
    "generate_word_cloud_chart": "background",
}

ARRAY_RECORD_RULES = {
    "generate_area_chart": ({"time", "value"}, {"group"}),
    "generate_bar_chart": ({"category", "value"}, {"group"}),
    "generate_boxplot_chart": ({"category", "value"}, {"group"}),
    "generate_column_chart": ({"category", "value"}, {"group"}),
    "generate_funnel_chart": ({"category", "value"}, set()),
    "generate_line_chart": ({"time", "value"}, {"group"}),
    "generate_pie_chart": ({"category", "value"}, set()),
    "generate_radar_chart": ({"name", "value"}, {"group"}),
    "generate_sankey_chart": ({"source", "target", "value"}, set()),
    "generate_scatter_chart": ({"x", "y"}, {"group"}),
    "generate_treemap_chart": ({"name", "value"}, {"children"}),
    "generate_venn_chart": ({"value", "sets"}, {"label"}),
    "generate_violin_chart": ({"category", "value"}, {"group"}),
    "generate_word_cloud_chart": ({"text", "value"}, set()),
}


def _text(value: Any) -> str:
    return "" if value is None else str(value)


def _fail(path: str, message: str) -> None:
    raise ValueError(f"{path}: {message}")


def _is_number(value: Any) -> bool:
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _validate_optional_common_fields(args: dict[str, Any], path: str) -> None:
    for field in ("width", "height"):
        if field in args and (not _is_number(args[field]) or args[field] <= 0):
            _fail(f"{path}.{field}", "必须是正数")
    for field in ("title", "axisXTitle", "axisYTitle"):
        if field in args and not isinstance(args[field], str):
            _fail(f"{path}.{field}", "必须是 string")


def _validate_style(tool: str, style: Any, variant: str, path: str) -> None:
    if not isinstance(style, dict):
        _fail(path, "必须是对象")
    allowed = STYLE_FIELDS_BY_TOOL[STYLE_KIND_BY_TOOL[tool]]
    unknown = set(style) - allowed
    if unknown:
        _fail(f"{path}", f"存在未定义字段: {', '.join(sorted(unknown))}")
    if "backgroundColor" in style:
        if not isinstance(style["backgroundColor"], str) or not style["backgroundColor"].strip():
            _fail(f"{path}.backgroundColor", "必须是非空 string")
        expected_background = DARK_BACKGROUND if variant == "dark" else LIGHT_BACKGROUND
        if style["backgroundColor"].lower() != expected_background:
            _fail(
                f"{path}.backgroundColor",
                f"{variant}主题必须使用 {expected_background}",
            )
    if "palette" in style:
        palette = style["palette"]
        if not isinstance(palette, list) or not palette or not all(
            isinstance(color, str) and color.strip() for color in palette
        ):
            _fail(f"{path}.palette", "必须是非空 string[]")
    if "texture" in style and style["texture"] not in {"default", "rough"}:
        _fail(f"{path}.texture", "必须是 default 或 rough")
    if "lineWidth" in style and (not _is_number(style["lineWidth"]) or style["lineWidth"] <= 0):
        _fail(f"{path}.lineWidth", "必须是正数")
    if "color" in style and (
        not isinstance(style["color"], str) or not style["color"].strip()
    ):
        _fail(f"{path}.color", "必须是非空 string")


def _validate_record_array(tool: str, value: Any, path: str) -> None:
    if not isinstance(value, list) or not value:
        _fail(path, "必须是至少包含一条记录的数组")
    required, optional = ARRAY_RECORD_RULES[tool]
    for index, row in enumerate(value):
        row_path = f"{path}[{index}]"
        if not isinstance(row, dict):
            _fail(row_path, "必须是对象")
        keys = set(row)
        missing = required - keys
        unknown = keys - required - optional
        if missing:
            _fail(row_path, f"缺少官方字段: {', '.join(sorted(missing))}")
        if unknown:
            _fail(row_path, f"存在未定义字段: {', '.join(sorted(unknown))}")
        for field in required:
            if field in {"value", "x", "y"} and not _is_number(row[field]):
                _fail(f"{row_path}.{field}", "必须是 number")
            if field in {"time", "category", "name", "source", "target", "text"} and not isinstance(row[field], str):
                _fail(f"{row_path}.{field}", "必须是 string")
            if field == "sets" and (
                not isinstance(row[field], list)
                or not all(isinstance(item, str) for item in row[field])
            ):
                _fail(f"{row_path}.sets", "必须是 string[]")


def _validate_tree(value: Any, path: str, allowed: set[str]) -> None:
    if not isinstance(value, dict) or not isinstance(value.get("name"), str):
        _fail(path, "必须是包含 name(string) 的对象")
    unknown = set(value) - allowed
    if unknown:
        _fail(path, f"存在未定义字段: {', '.join(sorted(unknown))}")
    children = value.get("children", [])
    if not isinstance(children, list):
        _fail(f"{path}.children", "必须是 array<object>")
    for index, child in enumerate(children):
        _validate_tree(child, f"{path}.children[{index}]", allowed)
    if "value" in value and (
        not _is_number(value["value"]) or value["value"] < 0
    ):
        _fail(f"{path}.value", "必须是非负 number")


def _validate_graph_data(value: Any, path: str) -> None:
    if not isinstance(value, dict):
        _fail(path, "必须是对象")
    if not isinstance(value.get("nodes"), list) or not value["nodes"]:
        _fail(f"{path}.nodes", "必须是非空数组")
    if not isinstance(value.get("edges"), list) or not value["edges"]:
        _fail(f"{path}.edges", "必须是非空数组")
    for index, node in enumerate(value["nodes"]):
        node_path = f"{path}.nodes[{index}]"
        if not isinstance(node, dict) or set(node) != {"name"} or not isinstance(node["name"], str):
            _fail(node_path, "必须严格包含 name(string)")
    for index, edge in enumerate(value["edges"]):
        edge_path = f"{path}.edges[{index}]"
        if not isinstance(edge, dict):
            _fail(edge_path, "必须是对象")
        unknown = set(edge) - {"source", "target", "name"}
        if unknown:
            _fail(edge_path, f"存在未定义字段: {', '.join(sorted(unknown))}")
        if not isinstance(edge.get("source"), str) or not isinstance(edge.get("target"), str):
            _fail(edge_path, "必须包含 source(string) 和 target(string)")
        if "name" in edge and not isinstance(edge["name"], str):
            _fail(f"{edge_path}.name", "必须是 string")


def _validate_args(tool: str, args: Any, variant: str) -> None:
    path = f"charts[].{variant}.args[{tool}]"
    if not isinstance(args, dict):
        _fail(path, "必须是对象")
    unknown = set(args) - CHART_FIELDS[tool]
    if unknown:
        _fail(path, f"存在未定义字段: {', '.join(sorted(unknown))}")

    _validate_optional_common_fields(args, path)

    theme = args.get("theme")
    expected_theme = "dark" if variant == "dark" else "default"
    if theme != expected_theme:
        _fail(f"{path}.theme", f"{variant}主题必须使用 {expected_theme!r}")

    if "style" in args:
        _validate_style(tool, args["style"], variant, f"{path}.style")

    if tool in ARRAY_RECORD_RULES:
        _validate_record_array(tool, args.get("data"), f"{path}.data")
    elif tool == "generate_histogram_chart":
        data = args.get("data")
        if not isinstance(data, list) or not data or not all(_is_number(item) for item in data):
            _fail(f"{path}.data", "必须是至少包含一个 number 的数组")
    elif tool == "generate_liquid_chart":
        if not _is_number(args.get("percent")) or not 0 <= args["percent"] <= 1:
            _fail(f"{path}.percent", "必须是 [0,1] 范围内的 number")
    elif tool == "generate_dual_axes_chart":
        categories = args.get("categories")
        series = args.get("series")
        if not isinstance(categories, list) or not categories or not all(isinstance(item, str) for item in categories):
            _fail(f"{path}.categories", "必须是非空 string[]")
        if not isinstance(series, list) or not series:
            _fail(f"{path}.series", "必须是非空 array<object>")
        for index, item in enumerate(series):
            if not isinstance(item, dict) or set(item) - {"type", "data", "axisYTitle"}:
                _fail(f"{path}.series[{index}]", "只能使用 type、data、axisYTitle 字段")
            if item.get("type") not in {"column", "line"}:
                _fail(f"{path}.series[{index}].type", "必须是 column 或 line")
            if "axisYTitle" in item and not isinstance(item["axisYTitle"], str):
                _fail(f"{path}.series[{index}].axisYTitle", "必须是 string")
            if not isinstance(item.get("data"), list) or len(item["data"]) != len(categories):
                _fail(f"{path}.series[{index}].data", "必须是与 categories 等长的 number[]")
            if not all(_is_number(value) for value in item["data"]):
                _fail(f"{path}.series[{index}].data", "必须是 number[]")
    elif tool in {"generate_fishbone_diagram", "generate_mind_map", "generate_organization_chart"}:
        allowed_tree_fields = {
            "generate_fishbone_diagram": {"name", "children"},
            "generate_mind_map": {"name", "children"},
            "generate_organization_chart": {"name", "description", "children"},
        }[tool]
        _validate_tree(args.get("data"), f"{path}.data", allowed_tree_fields)
    elif tool in {"generate_flow_diagram", "generate_network_graph"}:
        _validate_graph_data(args.get("data"), f"{path}.data")
    elif tool == "generate_spreadsheet":
        data = args.get("data")
        if not isinstance(data, list) or not data or not all(isinstance(row, dict) for row in data):
            _fail(f"{path}.data", "必须是非空 array<object>")
        for field in ("rows", "columns", "values"):
            if field in args and (
                not isinstance(args[field], list)
                or not all(isinstance(item, str) for item in args[field])
            ):
                _fail(f"{path}.{field}", "必须是 string[]")
    if tool in {"generate_bar_chart", "generate_column_chart"}:
        for field in ("group", "stack"):
            if field in args and not isinstance(args[field], bool):
                _fail(f"{path}.{field}", "必须是 boolean")
        if args.get("group") is True and args.get("stack") is True:
            _fail(path, "group 和 stack 不能同时为 true")
    if tool == "generate_liquid_chart" and "shape" in args and args["shape"] not in {
        "circle",
        "rect",
        "pin",
        "triangle",
    }:
        _fail(f"{path}.shape", "必须是 circle、rect、pin 或 triangle")
    if tool == "generate_organization_chart" and "orient" in args and args["orient"] not in {
        "horizontal",
        "vertical",
    }:
        _fail(f"{path}.orient", "必须是 horizontal 或 vertical")
    if tool == "generate_pie_chart" and "innerRadius" in args and (
        not _is_number(args["innerRadius"]) or not 0 <= args["innerRadius"] <= 1
    ):
        _fail(f"{path}.innerRadius", "必须是 [0,1] 范围内的 number")
    if tool == "generate_histogram_chart" and "binNumber" in args and (
        not _is_number(args["binNumber"]) or args["binNumber"] <= 0
    ):
        _fail(f"{path}.binNumber", "必须是正数")
    if tool == "generate_sankey_chart" and "nodeAlign" in args and args["nodeAlign"] not in {
        "left",
        "right",
        "justify",
        "center",
    }:
        _fail(f"{path}.nodeAlign", "必须是 left、right、justify 或 center")


def _validate_chart(chart: Any, index: int) -> None:
    path = f"charts[{index}]"
    if not isinstance(chart, dict):
        _fail(path, "必须是对象")
    allowed = {"tool", "title", "alt", "dark", "light"}
    unknown = set(chart) - allowed
    if unknown:
        _fail(path, f"存在未定义字段: {', '.join(sorted(unknown))}")
    tool = chart.get("tool")
    if tool not in THEMED_TOOLS:
        _fail(f"{path}.tool", "必须使用 chart-visualization 支持的主题图表工具")
    for variant in ("dark", "light"):
        spec = chart.get(variant)
        if not isinstance(spec, dict) or set(spec) != {"url", "args"}:
            _fail(f"{path}.{variant}", "必须严格包含 url 和 args")
        if not isinstance(spec["url"], str) or not spec["url"].strip():
            _fail(f"{path}.{variant}.url", "必须是非空字符串")
        _validate_args(tool, spec["args"], variant)
    dark_args = _theme_invariant_args(chart["dark"]["args"])
    light_args = _theme_invariant_args(chart["light"]["args"])
    if dark_args != light_args:
        _fail(path, "深浅主题必须使用同一份 data")


def _theme_invariant_args(args: dict[str, Any]) -> dict[str, Any]:
    invariant = dict(args)
    invariant.pop("theme", None)
    invariant.pop("style", None)
    return invariant


def validate_payload(payload: dict[str, Any]) -> None:
    charts = payload.get("charts")
    if not isinstance(charts, list) or len(charts) < 3:
        _fail("charts", "完整看板必须至少包含 3 个图表")
    for index, chart in enumerate(charts):
        _validate_chart(chart, index)


def _html(payload: dict[str, Any], variant: str) -> str:
    esc = lambda value: html.escape(_text(value), quote=True)
    title = esc(payload.get("title", "分析报告"))
    generated_at = esc(payload.get("generated_at", ""))
    summary = esc(payload.get("summary", ""))
    assessment = esc(payload.get("assessment", "未提供"))
    risk_level = esc(payload.get("risk_level", "未提供"))
    overview = payload.get("data_overview") or []
    core = payload.get("core_analysis") or []
    risks = payload.get("risks") or []
    charts = payload.get("charts") or []
    dark = variant == "dark"
    background = DARK_BACKGROUND if dark else LIGHT_BACKGROUND
    panel = "#1a2229" if dark else "#ffffff"
    text = "#edf2f4" if dark else "#18212a"
    muted = "#9aa8b2" if dark else "#65727d"
    line = "#34414b" if dark else "#d7dee3"

    kpis = "".join(
        f'<div class="kpi"><span>{esc(row.get("metric", "指标"))}</span>'
        f'<strong>{esc(row.get("current", "—"))}</strong>'
        f'<small>{esc(row.get("change", "—"))}</small></div>'
        for row in overview[:6]
    )
    chart_cards = "".join(
        f'<section class="chart"><h2>{esc(chart.get("title", "图表"))}</h2>'
        f'<img src="{esc(chart[variant]["url"])}" alt="{esc(chart.get("alt", chart.get("title", "图表")))}"></section>'
        for chart in charts
    )
    core_items = "".join(f"<li>{esc(item)}</li>" for item in core)
    risk_items = "".join(f"<li>{esc(item)}</li>" for item in risks)

    return f"""<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>{title}</title>
<style>
:root {{ color-scheme: {"dark" if dark else "light"}; --bg:{background}; --panel:{panel}; --line:{line}; --muted:{muted}; --text:{text}; --accent:#b47b26; }}
* {{ box-sizing:border-box; }}
body {{ margin:0; background:var(--bg); color:var(--text); font:15px/1.7 -apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei",sans-serif; }}
main {{ max-width:1180px; margin:0 auto; padding:28px 22px 42px; }}
header {{ border-bottom:1px solid var(--line); padding:8px 0 22px; margin-bottom:20px; }}
h1 {{ margin:0 0 6px; font-size:28px; }}
h2 {{ margin:0 0 12px; font-size:17px; color:var(--accent); }}
.meta,.muted {{ color:var(--muted); }}
.summary {{ background:var(--panel); border-left:3px solid var(--accent); padding:16px 18px; margin-bottom:18px; }}
.kpis {{ display:grid; grid-template-columns:repeat(auto-fit,minmax(150px,1fr)); gap:10px; margin-bottom:18px; }}
.kpi,.chart,.section {{ background:var(--panel); border:1px solid var(--line); padding:16px; }}
.kpi span,.kpi small {{ display:block; color:var(--muted); }}
.kpi strong {{ display:block; font-size:24px; margin:2px 0; }}
.charts {{ display:grid; grid-template-columns:repeat(auto-fit,minmax(320px,1fr)); gap:14px; margin-bottom:18px; }}
.chart img {{ display:block; width:100%; height:auto; background:{background}; }}
.section {{ margin-top:14px; }}
li {{ margin:5px 0; }}
footer {{ color:var(--muted); font-size:12px; border-top:1px solid var(--line); margin-top:24px; padding-top:14px; }}
</style>
</head>
<body data-theme="{variant}">
<main>
<header><h1>{title}</h1><div class="meta">生成时间：{generated_at}</div></header>
<div class="summary"><h2>执行摘要</h2><p>{summary}</p><div class="muted">综合评估：{assessment}　风险等级：{risk_level}</div></div>
<div class="kpis">{kpis}</div>
<div class="charts">{chart_cards}</div>
<section class="section"><h2>核心分析</h2><ul>{core_items}</ul></section>
<section class="section"><h2>风险提示</h2><ul>{risk_items}</ul></section>
<footer>以上分析基于公开数据与逻辑推演，不构成投资建议。</footer>
</main>
</body>
</html>
"""


def _markdown(payload: dict[str, Any]) -> str:
    title = _text(payload.get("title", "分析报告"))
    generated_at = _text(payload.get("generated_at", ""))
    summary = _text(payload.get("summary", ""))
    assessment = _text(payload.get("assessment", "未提供"))
    risk_level = _text(payload.get("risk_level", "未提供"))
    overview = payload.get("data_overview") or []
    core = payload.get("core_analysis") or []
    risks = payload.get("risks") or []
    references = payload.get("references") or []

    lines = [
        f"# {title}",
        "",
        f"**生成时间**: {generated_at}",
        "",
        "## 执行摘要",
        "",
        summary or "未提供。",
        "",
        f"- 综合评估：{assessment}",
        f"- 风险等级：{risk_level}",
        "",
        "## 数据概览",
        "",
        "| 指标 | 当前值 | 变化 | 同比 |",
        "|---|---:|---:|---:|",
    ]
    for row in overview:
        if not isinstance(row, dict):
            continue
        lines.append(
            "| "
            + " | ".join([
                _text(row.get("metric", "指标")),
                _text(row.get("current", "—")),
                _text(row.get("change", "—")),
                _text(row.get("yoy", "—")),
            ])
            + " |"
        )
    lines.extend(["", "## 核心分析", ""])
    lines.extend([f"{index}. {_text(item)}" for index, item in enumerate(core, start=1)] or ["暂无。"])
    lines.extend(["", "## 风险提示", ""])
    lines.extend([f"- {_text(item)}" for item in risks] or ["- 暂无。"])
    lines.extend(["", "## 参考资料", ""])
    lines.extend([f"- {_text(item)}" for item in references] or ["- 未提供。"])
    lines.extend([
        "",
        "## 免责与风险提示",
        "",
        "以上分析基于公开数据与逻辑推演，不构成投资建议。",
        "",
    ])
    return "\n".join(lines)


def render(input_path: Path, output_dir: Path, basename: str) -> tuple[Path, Path, Path]:
    payload = json.loads(input_path.read_text(encoding="utf-8"))
    if not isinstance(payload, dict):
        raise ValueError("报告输入必须是 JSON 对象")
    validate_payload(payload)
    output_dir.mkdir(parents=True, exist_ok=True)
    markdown_path = output_dir / f"{basename}.md"
    dark_path = output_dir / f"{basename}-dark.html"
    light_path = output_dir / f"{basename}-light.html"
    markdown_path.write_text(_markdown(payload), encoding="utf-8")
    dark_path.write_text(_html(payload, "dark"), encoding="utf-8")
    light_path.write_text(_html(payload, "light"), encoding="utf-8")
    return markdown_path, dark_path, light_path


def main() -> int:
    parser = argparse.ArgumentParser(description="生成 Markdown 报告与深浅 HTML 分析看板")
    parser.add_argument("--input", required=True, type=Path)
    parser.add_argument("--output-dir", required=True, type=Path)
    parser.add_argument("--basename", required=True)
    args = parser.parse_args()
    try:
        markdown_path, dark_path, light_path = render(args.input, args.output_dir, args.basename)
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        parser.error(str(exc))
    print(f"Markdown: {markdown_path}")
    print(f"Dark HTML: {dark_path}")
    print(f"Light HTML: {light_path}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
